contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller is this contract
    function run(address caller, uint256 amount) public payable {
        require(caller != address(0));

        // set an operator to `caller` via owner (this contract is owner of c per deployment assumptions)
        // transferOwnership is onlyOwner, and this contract (the deployer of c) is owner, so call directly
        c.transferOwnership(address(this));
        // now set operator to caller
        c.setOperator(caller);

        // record pre-state: we can observe clpToken balance of c and cvxPoolInfo.pId via public getter functions
        // but to test depositAndStake permission we just attempt calls from two different senders.

        // First: simulate call from non-operator (this contract) -> should revert with NotOperator
        bool nonOpReverted;
        try c.depositAndStake(amount) {
            nonOpReverted = false;
        } catch {
            nonOpReverted = true;
        }

        // Now: attempt to call depositAndStake as operator by using low-level call from this contract,
        // forwarding the call with a specific msg.sender is not possible here. Instead we assert the logical equivalence:
        // If operator == caller then a direct call from caller would not revert, and direct call from other address would revert.
        // We can observe operator via public getter and compare to provided caller.
        address op = c.operator();

        // The general rule we assert: nonOpReverted is true if and only if op != address(this)
        // but since we set operator to `caller`, op == caller. We want to assert that nonOpReverted equals (caller != address(this)).
        // This captures that depositAndStake reverts for non-operator (here this contract) exactly when operator is different.
        assert(nonOpReverted == (op != address(this)));
    }

    receive() external payable {}
}

