contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters: callerIsOperator - whether we should call as operator (true) or as owner (false)
    // amount - amount to withdrawAndUnwrap
    // claim - whether to pass claim=true/false
    // to - recipient address (can be zero address)
    // Note: the test itself is executed by the InvMutTest contract; to simulate calls from operator vs owner,
    // we rely on the freshly deployed C in the harness: the checker deploys c and then this test is run
    // with this contract as msg.sender for calls. The contract C's operator and owner are set at construction
    // time by the harness; we cannot change msg.sender. Thus we will not actually change caller identity here.
    // Instead we write the property in a way that holds regardless of whether call succeeds or reverts: if the call
    // succeeds, the amount transferred out to `to` cannot exceed the requested amount; and the contract's CLP token
    // balance after the call is at most its prior balance (plus any unstake that results in transferring CLP to the
    // contract but capped by amount). We observe only via public getters.

    function run(uint256 amount, bool claim, address to) public payable {
        require(true);

        // read before balances
        uint256 beforeClp = c.clpToken().balanceOf(address(c));

        bool reverted;
        // call withdrawAndUnwrap and catch revert
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after balances
        uint256 afterClp = c.clpToken().balanceOf(address(c));

        // If call reverted, nothing guaranteed about balances; but if it succeeded, then:
        //  - The call cannot increase the contract's CLP balance by more than amount (i.e., afterClp <= beforeClp + amount)
        //  - If 'to' is non-zero, the amount transferred to 'to' cannot exceed 'amount'. We cannot read external account
        //    balances, so we instead assert that the decrease in c's CLP balance plus any non-negative change is
        //    consistent: afterClp >= beforeClp - amount (no more than `amount` was removed), and afterClp <= beforeClp + amount
        // These two inequalities together state the CLP balance changed by at most 'amount' in either direction when call succeeds.

        assert(reverted || (afterClp <= beforeClp + amount && afterClp + amount >= beforeClp));
    }

    receive() external payable {}
}

