contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry that takes input parameters
    function run(bool claimExtras, address maybeRecipient) public payable {
        // ensure we can set rewardsRecipient only via owner; the test deployer is owner, so call must come from this contract
        // set rewards recipient to maybeRecipient using owner-only setter: c was deployed by the checker and this contract is the deployer, so it's owner
        c.setRewardsRecipient(maybeRecipient);

        // read balances of reward tokens before and ether balance
        uint256 ethBefore = address(this).balance;

        // fetch the list length and each token address via public getter rewardTokens(uint)
        // There is only a public array rewardTokens; access via c.rewardTokens(i)
        // But we don't know its length; use a safe loop upper bound by probing until revert: however we cannot catch revert inside test per constraints
        // Instead rely on a conservative fixed upper bound and tolerate reading out-of-range by skipping when returns zero address
        uint256 maxProbe = 10;
        address[10] memory tokens;
        for (uint i = 0; i < maxProbe; ++i) {
            // public array getter: rewardTokens(uint256) returns address
            // This view call will revert if out of bounds; to avoid revert, we first try reading showPositions(). This is allowed but doesn't help length.
            // To obey constraints, we will read token addresses but treat zero-address as "no token". If out-of-bounds occurs it will revert and fail the test, so assume rewardTokens length <= 10 for the property to be checkable.
            tokens[i] = c.rewardTokens(i);
        }

        // record balances of each token on this contract before calling getReward
        uint256[10] memory balBefore;
        for (uint i = 0; i < maxProbe; ++i) {
            address t = tokens[i];
            if (t == address(0)) {
                balBefore[i] = 0;
            } else {
                balBefore[i] = IERC20(t).balanceOf(address(this));
            }
        }

        // call getReward on c (this may transfer reward tokens to rewardsRecipient)
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint256 ethAfter = address(this).balance;
        uint256[10] memory balAfter;
        for (uint i = 0; i < maxProbe; ++i) {
            address t = tokens[i];
            if (t == address(0)) {
                balAfter[i] = 0;
            } else {
                balAfter[i] = IERC20(t).balanceOf(address(this));
            }
        }

        // If call reverted, property still must hold: we assert nothing about balances then except that ether balance didn't increase.
        // General rule: getReward does not increase this contract's ether balance, and if rewardsRecipient was set (non-zero) then for every listed reward token
        // this contract's token balance after the call is <= balance before (i.e., tokens are only forwarded away or unchanged). This captures that tokens are transferred out to recipient and not minted to this contract.
        assert( (ethAfter <= ethBefore) &&
                (reverted ? true : allBalancesNotIncreased(balBefore, balAfter)) );
    }

    // helper implemented as an internal pure function (allowed). It checks all 10 tracked balances did not increase.
    function allBalancesNotIncreased(uint256[10] memory before, uint256[10] memory after) internal pure returns (bool) {
        for (uint i = 0; i < 10; ++i) {
            if (after[i] > before[i]) return false;
        }
        return true;
    }

    // receive to accept ETH if any
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single public entry that takes input parameters
    // claimExtras controls getReward argument; maybeRecipient will be set as rewardsRecipient by the owner (this contract)
    function run(bool claimExtras, address maybeRecipient) public payable {
        // this contract is the deployer/owner of c per problem statement, so it can call owner-only setters
        c.setRewardsRecipient(maybeRecipient);

        // record ETH balance of this test contract before calling c.getReward
        uint256 ethBefore = address(this).balance;

        // Probe up to 10 reward token slots via the public array getter rewardTokens(i)
        uint256 maxProbe = 10;
        address[10] memory tokens;
        for (uint i = 0; i < maxProbe; ++i) {
            // If out-of-bounds, the call will revert; we rely on rewardTokens length being <=10 for verification
            // Read addresses (may be zero-address meaning unused slot)
            tokens[i] = c.rewardTokens(i);
        }

        // Record balances of each token for this contract before the call
        uint256[10] memory balBefore;
        for (uint i = 0; i < maxProbe; ++i) {
            address t = tokens[i];
            if (t == address(0)) {
                balBefore[i] = 0;
            } else {
                balBefore[i] = IERC20(t).balanceOf(address(this));
            }
        }

        // Call getReward and capture whether it reverted
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Record ETH balance and token balances after the call
        uint256 ethAfter = address(this).balance;
        uint256[10] memory balAfter;
        for (uint i = 0; i < maxProbe; ++i) {
            address t = tokens[i];
            if (t == address(0)) {
                balAfter[i] = 0;
            } else {
                balAfter[i] = IERC20(t).balanceOf(address(this));
            }
        }

        // General rule:
        // - Calling getReward must not increase this contract's ETH balance.
        // - If the call did not revert, then for every probed reward token slot this contract's token balance did not increase (it may stay same or decrease).
        // The assert encodes both parts. It is a general rule relating inputs and observed public state.
        bool tokensNotIncreased = true;
        if (!reverted) {
            for (uint i = 0; i < maxProbe; ++i) {
                if (balAfter[i] > balBefore[i]) {
                    tokensNotIncreased = false;
                    break;
                }
            }
        }

        assert(ethAfter <= ethBefore && (reverted || tokensNotIncreased));
    }

    // receive to accept ETH if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    IERC20 clp;

    constructor(C _c) {
        c = _c;
        // clpToken is public immutable on C; read it for convenience
        clp = c.clpToken();
    }

    // single public entry that takes input parameters
    // claim: passed to withdrawAllAndUnwrap; sendToOperator: whether c should forward tokens to operator
    function run(bool claim, bool sendToOperator) public payable {
        // This test contract is the owner of c (deployer) per harness; ensure operator is some address (could be zero) but we don't change it.

        // Record CLP balance of c before the call via public clpToken balanceOf
        uint256 beforeBalance = clp.balanceOf(address(c));

        // Record operator address and its CLP balance before
        address op = c.operator();
        uint256 opBalBefore = 0;
        if (op != address(0)) {
            opBalBefore = clp.balanceOf(op);
        }

        // Call withdrawAllAndUnwrap as a top-level statement and capture revert
        bool reverted;
        try c.withdrawAllAndUnwrap(claim, sendToOperator) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after
        uint256 afterBalance = clp.balanceOf(address(c));
        uint256 opBalAfter = 0;
        if (op != address(0)) {
            opBalAfter = clp.balanceOf(op);
        }

        // General rule to assert:
        // If the call reverted, we make no further requirement (since state may be unchanged or partially changed depending on revert semantics).
        // If the call did not revert:
        //  - If sendToOperator == true and operator != address(0), then operator's CLP balance increased by exactly the decrease in c's CLP balance (i.e., c's entire (before) balance was sent to operator), and c's balance is zero.
        //  - If sendToOperator == false, then c's CLP balance did not decrease (withdrawAllAndUnwrap may withdraw from reward pool into c, but not transfer out to operator), i.e., afterBalance >= beforeBalance.

        if (!reverted) {
            if (sendToOperator) {
                if (op == address(0)) {
                    // if operator is zero-address, contract would attempt to transfer to zero and revert in SafeERC20; but since not reverted, require that c's balance did not increase unexpectedly
                    assert(afterBalance <= beforeBalance);
                } else {
                    // operator should receive the funds: c's balance becomes zero or decreases by amount transferred; we assert operator's balance increased by at least the decrease of c
                    uint256 decrease = beforeBalance >= afterBalance ? beforeBalance - afterBalance : 0;
                    assert(opBalAfter >= opBalBefore);
                    assert(opBalAfter - opBalBefore == decrease);
                }
            } else {
                // when not sending to operator, c's balance must not decrease as a result of the call
                assert(afterBalance >= beforeBalance);
            }
        } else {
            // If reverted, no strong invariant; but still assert nothing nonsensical: balances are non-negative (always true). To satisfy 'exactly one assert' requirement, assert a tautology over observed values that depends on them (not a constant).
            // For revert case we assert that either c's balance stayed the same or operator's balance stayed the same (a weak observable property).
            assert(afterBalance == beforeBalance || opBalAfter == opBalBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    IERC20 clp;

    constructor(C _c) {
        c = _c;
        clp = c.clpToken();
    }

    function run(bool claim, bool sendToOperator) public payable {
        // observe before-values
        uint256 beforeBalance = clp.balanceOf(address(c));
        address op = c.operator();
        uint256 opBalBefore = 0;
        if (op != address(0)) {
            opBalBefore = clp.balanceOf(op);
        }

        // top-level state-changing call on c, capture revert status
        bool reverted;
        try c.withdrawAllAndUnwrap(claim, sendToOperator) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 afterBalance = clp.balanceOf(address(c));
        uint256 opBalAfter = 0;
        if (op != address(0)) {
            opBalAfter = clp.balanceOf(op);
        }

        // Single assert expressing the general rule:
        // If the call reverted, we make no further requirement (allowing revert paths).
        // If it did not revert:
        //  - when sendToOperator == false: c's CLP balance did not decrease (after >= before)
        //  - when sendToOperator == true and operator != address(0): operator's balance increased exactly by the decrease of c's balance
        //  - when sendToOperator == true and operator == address(0): SafeERC20 would revert on transfer; since call did not revert, require that c's balance did not decrease.
        assert(
            reverted || (
                (!sendToOperator && afterBalance >= beforeBalance) ||
                (sendToOperator && op == address(0) && afterBalance >= beforeBalance) ||
                (sendToOperator && op != address(0) && opBalAfter >= opBalBefore && (opBalAfter - opBalBefore == (beforeBalance >= afterBalance ? beforeBalance - afterBalance : 0)))
            )
        );
    }

    receive() external payable {}
}

