contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that withdrawAndUnwrap(amount, claim, to) when invoked by an authorized caller
    // will not cause the contract's clpToken balance to increase, and will not transfer out more
    // CLP tokens than `amount` (i.e., the function cannot enlarge the contract's CLP balance and
    // cannot send out more than requested). We call as owner to satisfy authorization.
    function run(uint256 amount, bool claim, address to) public payable {
        require(to != address(0) && to != address(this), "choose non-zero, not-self recipient");

        // read balance before
        uint256 before = c.clpToken().balanceOf(address(c));

        // We will call withdrawAndUnwrap as the owner. Since the checker deploys a fresh C and
        // then deploys this InvMutTest passing that C into the constructor, this contract is the
        // deployer of C and thus is the owner. So calling c.withdrawAndUnwrap(...) from here
        // will be from owner() and is allowed by onlyOperatorOrOwner.

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balance after
        uint256 after = c.clpToken().balanceOf(address(c));

        // If the call reverted, the contract balance must be unchanged.
        // If it did not revert, the contract's CLP balance must be <= before (it should not increase),
        // and the amount sent out cannot exceed the requested amount `amount`.
        // We cannot directly observe the transfer amount to `to`, but we can assert that
        // before - after <= amount when before >= after, and when after > before that is disallowed.

        // Construct conditions:
        // 1) If reverted -> after == before
        // 2) If not reverted -> after <= before && (before - after) <= amount

        assert(
            (reverted && after == before) ||
            (!reverted && after <= before && (before - after) <= amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
