    constructor(C _c) { c = _c; }

    // Test the withdrawAndUnwrap behavior when called by the owner (this contract is the deployer/owner)
    function run(uint256 amount, bool claim, address to) public payable {
        // avoid sending to C itself to keep observations meaningful
        require(to != address(c), "recipient must not be C");

        // read balance before
        uint256 before = c.clpToken().balanceOf(address(c));

        // Call withdrawAndUnwrap as owner (this contract is owner of C)
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

