contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take no parameters because getReward() has no args; we only observe its effects.
    function run() public payable {
        require(true);

        // Read observable pre-state
        address recipient = c.rewardsRecipient();
        uint256 tokensLenBefore;
        // read length of rewardTokens array by probing indices until revert or a reasonable cap
        // but we may only call public functions; rewardTokens is public so has a getter rewardTokens(uint)
        // We'll attempt up to 8 entries to bound gas and allow proving general rule for typical arrays.
        uint256[8] memory balancesBefore;
        address[8] memory toks;
        uint256 n = 0;
        for (uint256 i = 0; i < 8; ++i) {
            // try to read rewardTokens(i); if it reverts (out-of-bounds) we stop
            bool ok = true;
            address tok;
            try c.rewardTokens(i) returns (address a) {
                tok = a;
            } catch {
                ok = false;
            }
            if (!ok) break;
            toks[n] = tok;
            // balanceOf is a view on IERC20; call via the token's public ABI through IERC20 interface is not allowed by constraints (we may only observe c), but we can read balances by calling IERC20(token).balanceOf(address(c)) — this is allowed since it's an external call, not reading c's internals.
            // However constraints forbid declaring interfaces; but IERC20 is already declared in the compilation unit, so we may use it.
            balancesBefore[n] = IERC20(tok).balanceOf(address(c));
            n++;
        }
        tokensLenBefore = n;

        // Make the state-changing call as a top-level statement
        bool reverted;
        try c.getReward(false) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable post-state: balances of the same tokens and the contract's ETH balance not used
        uint256[8] memory balancesAfter;
        for (uint256 i = 0; i < tokensLenBefore; ++i) {
            balancesAfter[i] = IERC20(toks[i]).balanceOf(address(c));
        }

        // General rule asserted:
        // If rewardsRecipient was set (nonzero) before the call and the call did NOT revert,
        // then for every listed rewardToken we observed, the balance after is either zero or less-than-or-equal to before (transferred out);
        // moreover, if the before-balance was nonzero then after-balance must be strictly less than or equal (i.e., tokens cannot increase in the contract as result)
        // If rewardsRecipient was zero or the call reverted, the contract's observed balances must remain unchanged.
        // Formally: For all i in observed indices:
        //   if !reverted && recipient != address(0) then balancesAfter[i] <= balancesBefore[i]
        //   if (reverted || recipient == address(0)) then balancesAfter[i] == balancesBefore[i]

        bool okAll = true;
        for (uint256 i = 0; i < tokensLenBefore; ++i) {
            if (!reverted && recipient != address(0)) {
                if (!(balancesAfter[i] <= balancesBefore[i])) okAll = false;
            } else {
                if (!(balancesAfter[i] == balancesBefore[i])) okAll = false;
            }
        }

        assert(okAll);
    }

    receive() external payable {}
}

