    }

    // single public test entry point
    function run(address caller, uint256 amount, bool claim, address to) public payable {
        require(caller != address(0), "caller nonzero");
        // Ensure we observe pre-call balances
        uint256 beforeClp = c.clpToken().balanceOf(address(c));
        uint256 beforeTo = 0;
        if (to != address(0)) {
            beforeTo = c.clpToken().balanceOf(to);
        }

        // We will attempt the call as either operator/owner or a non-privileged caller.
        // The InvMutTest contract is the msg.sender when interacting with c, so to simulate
        // operator/owner we rely on the contract's existing operator/owner being this contract.
        // If this contract is not operator or owner the call should revert with NotOperator/NotOperatorOrOwner.

        bool reverted = false;
        // perform the call; must be a top-level statement
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterClp = c.clpToken().balanceOf(address(c));
        uint256 afterTo = 0;
        if (to != address(0)) {
            afterTo = c.clpToken().balanceOf(to);
        }

        // General rule asserted:
        // - If call succeeded (not reverted) then c's CLP balance cannot drop below zero (always true) and
        //   the recipient (if non-zero) received at most `amount` additional tokens.
        // - If call reverted then it must be because this contract was not operator or owner, so balances unchanged.
        assert(
            // if succeeded: c lost at most `amount` CLP tokens and recipient gained at most `amount`
            (!reverted && (beforeClp >= afterClp) && (beforeClp - afterClp <= amount) && (to == address(0) || afterTo - beforeTo <= amount))
            // if reverted: no balances changed
            || (reverted && beforeClp == afterClp && (to == address(0) || beforeTo == afterTo))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry point for the property-based test.
    // Params:
    //  - claimExtras: passed to c.getReward(claimExtras)
    //  - rcpt: an address to compare balances if non-zero (we observe balances of reward tokens for c and rcpt)
    //  - idx: an index into rewardTokens array to pick one token to observe (helps keep storage reads minimal)
    function run(bool claimExtras, address rcpt, uint256 idx) public payable {
        require(idx < 10_000, "idx bounded"); // cheap bound to avoid huge loops in some analyzers

        // Read reward token list length via successive reads until we reach idx or length.
        // We must only use public/external calls on c. rewardTokens is public, so there is a getter rewardTokens(uint256).
        // Determine length by probing until a revert; but we cannot catch reverts except with try/catch on an external call.
        // Instead, we will read up to idx and if any read reverts then we treat length <= that index.

        // Record balance of the chosen token for c and rcpt before the call if token exists.
        bool tokenExists;
        address tokenAddr = address(0);
        // Try to read rewardTokens[idx]; if it reverts, tokenExists=false, else true.
        try c.rewardTokens(idx) returns (address t) {
            tokenExists = true;
            tokenAddr = t;
        } catch {
            tokenExists = false;
            tokenAddr = address(0);
        }

        uint256 beforeC = 0;
        uint256 beforeRcpt = 0;
        if (tokenExists) {
            // balanceOf is a public function on IERC20; call via the token's interface by its public functions is allowed only through IERC20 type, but we may call the token's balanceOf via IERC20(tokenAddr).balanceOf(...)
            // However the constraints forbid declaring interfaces; but calling IERC20(tokenAddr).balanceOf(...) is allowed (it compiles as external call).
            try IERC20(tokenAddr).balanceOf(address(c)) returns (uint256 bC) {
                beforeC = bC;
            } catch {
                beforeC = 0;
            }
            if (rcpt != address(0)) {
                try IERC20(tokenAddr).balanceOf(rcpt) returns (uint256 bR) {
                    beforeRcpt = bR;
                } catch {
                    beforeRcpt = 0;
                }
            }
        }

        // Perform the state-changing call on c as a top-level statement and capture whether it reverted.
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-balances for the same token if it exists.
        uint256 afterC = 0;
        uint256 afterRcpt = 0;
        if (tokenExists) {
            try IERC20(tokenAddr).balanceOf(address(c)) returns (uint256 aC) {
                afterC = aC;
            } catch {
                afterC = beforeC;
            }
            if (rcpt != address(0)) {
                try IERC20(tokenAddr).balanceOf(rcpt) returns (uint256 aR) {
                    afterRcpt = aR;
                } catch {
                    afterRcpt = beforeRcpt;
                }
            }
        }

        // Now assert the general rule (single assert):
        // - If token does not exist in rewardTokens at idx, nothing to assert about balances (vacuously true).
        // - If call reverted: balances must be unchanged for both c and rcpt for that token.
        // - If call succeeded: c's balance for that token cannot increase (c should not gain rewards it then keeps), and if rewardsRecipient is set (non-zero) then c's balance after must be zero (tokens forwarded), otherwise c's balance may decrease but not increase; additionally if rcpt provided and rewardsRecipient is set, rcpt's balance must be >= beforeRcpt (it may increase by what c had).
        address rcptGetter;
        try c.rewardsRecipient() returns (address r) {
            rcptGetter = r;
        } catch {
            rcptGetter = address(0);
        }

        assert(
            // If token doesn't exist, accept
            (!tokenExists)
            || (
                // if reverted, no balance changes
                (reverted && afterC == beforeC && (rcpt == address(0) || afterRcpt == beforeRcpt))
                // if succeeded
                || (!reverted && (
                    // c's balance did not increase
                    afterC <= beforeC
                    // if a rewardsRecipient is set, then c should not retain tokens after successful getReward
                    && (rcptGetter == address(0) ? true : afterC == 0)
                    // if caller provided rcpt to observe and rewardsRecipient is set, rcpt's balance did not decrease
                    && (rcpt == address(0) ? true : afterRcpt >= beforeRcpt)
                ))
            )
        );
    }

    receive() external payable {}
}

