        // and capture whether it reverted.

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // General rule: withdrawAndUnwrap cannot increase the contract's clpToken balance, and if it succeeded
        // then the contract's balance decreased by at most 'amount' (i.e., before - after <= amount).
        // Also if the call reverted then balances must be unchanged.

        // compute whether callerKind corresponds to an allowed caller (operator or owner)
        address op = c.operator();
        address own = c.owner();
        // Our test contract is the msg.sender for the call above. Check if this contract equals operator or owner.
        bool isAllowedCaller = (address(this) == op) || (address(this) == own);

        // Build the asserted invariant combining observed values and revert flag.
        // 1) afterBalance <= beforeBalance (never increases)
        // 2) if reverted then afterBalance == beforeBalance
        // 3) if not reverted then (beforeBalance - afterBalance) <= amount
        // Avoid underflow in subtraction by rearranging: afterBalance >= beforeBalance ? diff = 0 : diff = beforeBalance - afterBalance

        uint256 diff;
        if (afterBalance >= beforeBalance) {
            diff = 0;
        } else {
            diff = beforeBalance - afterBalance;
        }

        assert(
            // never increases
            afterBalance <= beforeBalance
            // revert implies unchanged
            && (reverted ? afterBalance == beforeBalance : true)
            // success implies decrease at most amount
            && (!reverted ? diff <= amount : true)
        );
    }

    receive() external payable {}
}

