        } catch {
            reverted = true;
        }

        // observe post-state
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // compute non-negative decrease (avoid underflow)
        uint256 decrease = afterBalance >= beforeBalance ? 0 : (beforeBalance - afterBalance);

        // General rule asserted:
        // 1) afterBalance never exceeds beforeBalance (can't increase)
        // 2) if the call reverted then balance unchanged
        // 3) if the call succeeded then the decrease is at most the requested amount
        assert(
            afterBalance <= beforeBalance
            && (reverted ? (afterBalance == beforeBalance) : true)
            && (!reverted ? (decrease <= amount) : true)
        );
    }

    receive() external payable {}
}

