contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: amount to deposit and an address to act as operator
    function run(uint256 amount, address potentialOperator) public payable {
        require(address(this).balance >= 0);
        // Record initial observable values
        address clp = address(c.clpToken());
        uint256 beforeBalance = IERC20(clp).balanceOf(address(c));
        // We cannot observe allowance of c to booster directly (allowance from c), but we can observe that
        // when pool is shutdown depositAndStake should not call booster.deposit and therefore should not
        // attempt to increase allowance (which would have required a call to clpToken.allowance from within c and then an approve via SafeERC20)
        // Observable effect we can check: when pool is shutdown, calling depositAndStake must not revert and must not change c's clp balance.

        // Prepare: set operator in c to potentialOperator by calling setOperator as owner. The test contract is the deployer of c per harness, but we are not owner — cannot call setOperator. So instead we will call depositAndStake as msg.sender = this contract and rely on behavior via onlyOperator.
        // We will attempt the call and record whether it reverted due to NotOperator or performed no state change when shutdown is true.

        // Query whether booster.poolInfo(pId).shutdown via c.isCvxShutdown()
        bool shutdown = c.isCvxShutdown();

        // Attempt call and observe revert flag
        bool reverted = false;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read observable clpToken balance again
        uint256 afterBalance = IERC20(clp).balanceOf(address(c));

        // General rule to assert:
        // If pool is shutdown then depositAndStake must be a no-op (it does not change c's clp token balance) and must not revert due to internal logic (it may still revert for operator check). However operator check will revert when caller is not operator; since our caller is not guaranteed operator, we assert the following general invariant:
        // If depositAndStake did NOT revert, then when isCvxShutdown() was true it must NOT have changed clp token balance; and when isCvxShutdown() was false it may change balance or allowance (we can't observe allowance) so we don't constrain that case.

        assert(reverted || (shutdown ? (beforeBalance == afterBalance) : true));
    }

    // minimal interface needed for ERC20 calls
    receive() external payable {}
}

